        uint256 contractBalanceAfter = maliciousToken.balanceOf(address(wizardPay));
        uint256 recipientBalanceAfter = maliciousToken.balanceOf(recipient);

        // Assert transfer call "succeeded" (transaction didn't revert)
        assertTrue(success, "Transaction should not revert");

        // Assert balances remain unchanged (transfer failed but wasn't detected)
        assertEq(
            contractBalanceAfter,
            contractBalanceBefore,
            "Contract token balance should remain unchanged"
        );
        assertEq(
